pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 firstUnlock, uint256 secondUnlock) public {
        // 1. (optional) vm.assume(...) / bound(...) to keep params in the ADMISSIBLE domain (keep it WIDE)
        // We want two puts by the same user where first sets a future unlock,
        // and second supplies a strictly smaller unlock.
        vm.assume(firstUnlock > block.timestamp);
        vm.assume(secondUnlock < firstUnlock);
        // 2. (optional) vm.deal/vm.prank/vm.warp to set up the scenario; drive c through `Put`
        address user = address(0x1000);
        vm.deal(user, 2 ether);

        vm.prank(user);
        c.Put{value: 1 ether}(firstUnlock);

        // warp forward so timestamps differ but still before firstUnlock
        vm.warp(block.timestamp + 1 days);
        vm.assume(block.timestamp < firstUnlock);

        vm.prank(user);
        c.Put{value: 1 ether}(secondUnlock);

        // 3. exactly one assertTrue(<general fact reading c>) the reference holds for all inputs and the bug breaks
        uint storedUnlock = c.Acc(user).unlockTime;
        assertTrue(storedUnlock >= firstUnlock);
    }
}

