pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 msgValue) public {
        // Keep unlockTime in a wide admissible range. Ensure it differs from the
        // current timestamp so the exact update matters for the assertion.
        vm.assume(unlockTime > block.timestamp);

        // Keep value within reasonable range; avoid overflow in the test setup but
        // do not constrain it to a single edge value.
        msgValue = bound(msgValue, 0.1 ether, 100 ether);

        address actor = address(0x1234);
        vm.deal(actor, msgValue);

        // Drive the entry point under test.
        vm.prank(actor);
        c.Put{value: msgValue}(unlockTime);

        // The recorded unlockTime in the Acc mapping must equal the last log entry's
        // Time field, because LogFile.AddMessage should be called *after* setting
        // acc.unlockTime. The reference contract obeys this for all admissible inputs;
        // the buggy version violates it when the logged timestamp is the previous value.
        (uint storedUnlockTime, ) = c.Acc(actor);
        ( , , , uint logTime) = c.LogFile().History(c.LogFile().History.length - 1);

        assertEq(storedUnlockTime, logTime);
    }
}

