    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 am, uint256 putVal, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(putVal >= 1 ether);
        vm.assume(am > 0 && am <= putVal);
        unlockTime = bound(unlockTime, 0, type(uint256).max - 1);
        vm.deal(actor, putVal);
        vm.prank(actor);
        c.Put{value: putVal}(unlockTime);
        vm.warp(unlockTime + 1);
        uint256 balBefore = actor.balance;
        vm.prank(actor);
        try c.Collect(am) { } catch { }
        uint256 balAfter = actor.balance;
        assertTrue(balAfter - balBefore == am);
    }
}

