pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialBalance, uint256 am, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(am <= initialBalance);
        vm.assume(initialBalance >= c.MinSum());
        vm.assume(am <= initialBalance);
        vm.assume(am > 0);
        vm.deal(actor, initialBalance);
        vm.prank(actor);
        c.Put{value: initialBalance}(block.timestamp);
        uint256 balanceBefore = c.Acc(actor).balance;
        vm.warp(block.timestamp + 1);
        vm.prank(actor);
        try c.Collect(am) { } catch { }
        uint256 balanceAfter = c.Acc(actor).balance;
        assertTrue(balanceAfter == balanceBefore - am);
    }
}

