pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount0, uint256 depositAmount1, uint256 unlockTime0, uint256 unlockTime1, uint256 collectAmount) public {
        vm.assume(depositAmount0 <= 1000 ether);
        vm.assume(depositAmount1 <= 1000 ether);
        vm.assume(unlockTime0 <= block.timestamp + 365 days);
        vm.assume(unlockTime1 <= block.timestamp + 365 days);
        vm.assume(collectAmount <= depositAmount0 + depositAmount1);

        address actor = address(0x12345);
        vm.deal(actor, depositAmount0 + depositAmount1);

        vm.prank(actor);
        c.Put{value: depositAmount0}(unlockTime0);
        vm.prank(actor);
        c.Put{value: depositAmount1}(unlockTime1);

        (uint unlockTime, uint balance) = c.Acc(actor);
        if (balance >= c.MinSum() && balance >= collectAmount && block.timestamp > unlockTime) {
            vm.warp(block.timestamp + 1 days);

            uint256 balanceBefore = address(actor).balance;
            vm.prank(actor);
            c.Collect(collectAmount);
            uint256 balanceAfter = address(actor).balance;

            assertTrue(balanceAfter - balanceBefore <= depositAmount0 + depositAmount1);
        }
    }
}
